INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Monopol in der IT immer illegal ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Legalität hängt von Gesetzen ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend illegal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein Monopol in der IT analysiere?', 3, '[{"text": "Marktmacht", "correct": true, "because": "Bestimmt Einfluss"}, {"text": "Schnellste Analyse", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein Monopol in der IT?', 5, '[{"text": "Ein einziger Anbieter", "correct": true, "because": "Kern des Monopols"}, {"text": "Hohe Markteintrittsbarrieren", "correct": true, "because": "Schützt Position"}, {"text": "Büromöbel", "correct": false, "because": "Kein Merkmal"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Monopol kann Preise frei bestimmen. b) Es gibt immer Wettbewerb.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Wettbewerb"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Monopol in der IT untersuche?', 4, '[{"text": "Marktanteil", "correct": false, "because": "Zeigt Dominanz"}, {"text": "Kundenoptionen", "correct": false, "because": "Fehlen bei Monopol"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Monopol in der IT immer nachteilig für Kunden ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kann Vorteile bieten"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich ein Monopol in der IT analysiere?', 3, '[{"text": "Marktdynamik verstehen", "correct": true, "because": "Beeinflusst Strategie"}, {"text": "Schnellste Analyse", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Weniger Daten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein Monopol in der IT?', 5, '[{"text": "Preissetzungsmacht", "correct": true, "because": "Kein Wettbewerb"}, {"text": "Exklusive Technologie", "correct": true, "because": "Schützt Position"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Monopol kann Innovationen fördern. b) Es gibt immer Alternativen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Alternativen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Monopol in der IT zu analysieren?', 4, '[{"text": "Marktanteile", "correct": false, "because": "Zeigen Dominanz"}, {"text": "Wettbewerbsanalyse", "correct": false, "because": "Fehlen bei Monopol"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Monopol in der IT immer nachteilig?', 2, '[{"text": "Nein", "correct": true, "because": "Kann Vorteile bieten"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile kann ein Monopol in der IT haben?', 4, '[{"text": "Hohe Innovationskraft", "correct": true, "because": "Ressourcen verfügbar"}, {"text": "Einheitliche Standards", "correct": true, "because": "Vereinfacht Nutzung"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Monopol nur in der Hardware existiert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um ein Monopol in der IT zu bewerten?', 3, '[{"text": "Marktanalyse", "correct": true, "because": "Zeigt Dominanz"}, {"text": "Schnellste Methode", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Monopol kann Preise erhöhen. b) Es ist immer vorteilhaft für Kunden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht immer vorteilhaft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei einem Monopol in der IT?', 5, '[{"text": "Markteintrittsbarrieren", "correct": true, "because": "Schützen Monopol"}, {"text": "Preissetzung", "correct": true, "because": "Bestimmt Markt"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich ein Monopol in der IT analysiere?', 3, '[{"text": "Marktdominanz", "correct": false, "because": "Kern des Monopols"}, {"text": "Wettbewerbsdruck", "correct": false, "because": "Fehlt bei Monopol"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Monopol Innovationen behindern?', 3, '[{"text": "Ja", "correct": true, "because": "Fehlender Wettbewerb"}, {"text": "Nein", "correct": false, "because": "Nicht immer förderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Monopol immer staatlich reguliert wird?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Gesetzen"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für ein Monopol in der IT?', 4, '[{"text": "Marktbeherrschung", "correct": true, "because": "Definiert Monopol"}, {"text": "Schnellste Analyse", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
